Rules.InvariantScript:
// First visit: seed the tunables. Later visits keep whatever the user set.
If(!Coalesce(gInit, false),
    Set(gInit, true);
    Set(gSpeed, 7);
    Set(gRadius, 14);
    Set(gSensor, 90);
    Set(gBlocks, 5);
    Set(gDrift, 1);
    Set(gAuto, false);
    Set(gPlaying, true);
    // Build the world: walls + paddle + random drifting blocks. Same code as the Shuffle button.
    With(
        {picked: FirstN(Shuffle(Cells), gBlocks)},
        ClearCollect(
            colObstacles,
            Walls,
            {Id: 0, Name: "Paddle", Kind: "paddle", X: (FieldW - PaddleW) / 2, Y: FieldH - 30, W: PaddleW, H: 16, VX: 0, VY: 0},
            ForAll(
                Sequence(gBlocks) As s,
                With(
                    {c: Index(picked, s.Value), w: RandBetween(50, 140), h: RandBetween(30, 120)},
                    {
                        Id: s.Value,
                        Name: "Block " & s.Value,
                        Kind: "block",
                        X: c.Col * 225 + RandBetween(30, 195 - w),
                        Y: 10 + c.Row * 270 + RandBetween(30, 230 - h),
                        W: w,
                        H: h,
                        VX: (RandBetween(0, 1) * 2 - 1) * RandBetween(4, 16) / 10,
                        VY: (RandBetween(0, 1) * 2 - 1) * RandBetween(2, 10) / 10
                    }
                )
            )
        )
    );
    Set(gPos, {x: FieldW / 2, y: FieldH / 2});
    Set(gDir, {x: Cos(Radians(-35)), y: Sin(Radians(-35))});
    Set(gHits, 0);
    Set(gSaves, 0);
    Set(gMisses, 0);
    Set(gTick, 0);
    Set(gLastHitTick, -100);
    Set(gLastHit, "")
)

"data:image/svg+xml;utf8," & EncodeUrl(
    "<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 900 600'>" &
    // paddle lane
    "<line x1='0' y1='" & Px(FieldH - LaneH) & "' x2='900' y2='" & Px(FieldH - LaneH) & "' stroke='#FFFFFF' stroke-opacity='0.08' stroke-dasharray='2 6'/>" &
    // drifting blocks (the nearest one takes the threat colour)
    Concat(
        Filter(colObstacles, Kind = "block"),
        "<rect x='" & Px(X) & "' y='" & Px(Y) & "' width='" & Px(W) & "' height='" & Px(H) & "' rx='4' fill='" &
        If(!IsBlank(Nearest) && Id = Nearest.Id, ThreatHex, "#2F3A5A") & "' fill-opacity='" &
        If(!IsBlank(Nearest) && Id = Nearest.Id, "0.35", "1") & "' stroke='" &
        If(!IsBlank(Nearest) && Id = Nearest.Id, ThreatHex, "#4A5578") & "' stroke-width='1.5'/>"
    ) &
    // paddle
    With(
        {p: LookUp(colObstacles, Kind = "paddle")},
        If(IsBlank(p), "",
            "<rect x='" & Px(p.X) & "' y='" & Px(p.Y) & "' width='" & Px(p.W) & "' height='" & Px(p.H) & "' rx='8' fill='" &
            If(!IsBlank(Nearest) && Nearest.Id = 0, ThreatHex, "#4FC3F7") & "'/>"
        )
    ) &
    // gap line: ball centre to the closest point on the nearest thing
    If(IsBlank(Nearest), "",
        "<line x1='" & Px(gPos.x) & "' y1='" & Px(gPos.y) & "' x2='" & Px(NearestPt.x) & "' y2='" & Px(NearestPt.y) & "' stroke='" & ThreatHex & "' stroke-width='1.5' stroke-dasharray='4 4'/>" &
        "<circle cx='" & Px(NearestPt.x) & "' cy='" & Px(NearestPt.y) & "' r='3' fill='" & ThreatHex & "'/>"
    ) &
    // predicted impact: ray along the heading to the contact position
    If(IsBlank(NextHit), "",
        "<line x1='" & Px(gPos.x) & "' y1='" & Px(gPos.y) & "' x2='" & Px(gPos.x + Vel.x * NextHit.T) & "' y2='" & Px(gPos.y + Vel.y * NextHit.T) & "' stroke='#FFC857' stroke-width='1' stroke-dasharray='2 4'/>" &
        "<circle cx='" & Px(gPos.x + Vel.x * NextHit.T) & "' cy='" & Px(gPos.y + Vel.y * NextHit.T) & "' r='" & Px(gRadius) & "' fill='none' stroke='#FFC857' stroke-opacity='0.7' stroke-dasharray='3 3'/>"
    ) &
    // sensor range ring
    "<circle cx='" & Px(gPos.x) & "' cy='" & Px(gPos.y) & "' r='" & Px(gRadius + gSensor) & "' fill='none' stroke='#4FC3F7' stroke-opacity='0.35' stroke-dasharray='6 6'/>" &
    // hit flash
    If(gTick - gLastHitTick < 6,
        "<circle cx='" & Px(gPos.x) & "' cy='" & Px(gPos.y) & "' r='" & Px(gRadius + 6 + (gTick - gLastHitTick) * 4) & "' fill='none' stroke='#FF5A5A' stroke-width='2' stroke-opacity='" & Px(1 - (gTick - gLastHitTick) / 6) & "'/>",
        ""
    ) &
    // the ball, rimmed with the threat colour, plus a heading tick
    "<circle cx='" & Px(gPos.x) & "' cy='" & Px(gPos.y) & "' r='" & Px(gRadius) & "' fill='#FFFFFF' stroke='" & ThreatHex & "' stroke-width='3'/>" &
    "<line x1='" & Px(gPos.x) & "' y1='" & Px(gPos.y) & "' x2='" & Px(gPos.x + gDir.x * (gRadius - 3)) & "' y2='" & Px(gPos.y + gDir.y * (gRadius - 3)) & "' stroke='#0D101B' stroke-width='2' stroke-linecap='round'/>" &
    "</svg>"
)

// New world: walls + paddle + random drifting blocks; ball back to the centre; counters reset.
With(
    {picked: FirstN(Shuffle(Cells), gBlocks)},
    ClearCollect(
        colObstacles,
        Walls,
        {Id: 0, Name: "Paddle", Kind: "paddle", X: (FieldW - PaddleW) / 2, Y: FieldH - 30, W: PaddleW, H: 16, VX: 0, VY: 0},
        ForAll(
            Sequence(gBlocks) As s,
            With(
                {c: Index(picked, s.Value), w: RandBetween(50, 140), h: RandBetween(30, 120)},
                {
                    Id: s.Value,
                    Name: "Block " & s.Value,
                    Kind: "block",
                    X: c.Col * 225 + RandBetween(30, 195 - w),
                    Y: 10 + c.Row * 270 + RandBetween(30, 230 - h),
                    W: w,
                    H: h,
                    VX: (RandBetween(0, 1) * 2 - 1) * RandBetween(4, 16) / 10,
                    VY: (RandBetween(0, 1) * 2 - 1) * RandBetween(2, 10) / 10
                }
            )
        )
    )
);
Reset(sldArnPaddle);
Set(gPos, {x: FieldW / 2, y: FieldH / 2});
Set(gDir, {x: Cos(Radians(-35)), y: Sin(Radians(-35))});
Set(gHits, 0);
Set(gSaves, 0);
Set(gMisses, 0);
Set(gTick, 0);
Set(gLastHitTick, -100);
Set(gLastHit, "")

// ============ one tick of the world. The ball knows nothing but what Sensor says right now. ============
// 0. The paddle's velocity for this tick is wherever the slider is minus where the paddle is.
With(
    {pad: LookUp(colObstacles, Kind = "paddle")},
    If(!IsBlank(pad), Patch(colObstacles, pad, {VX: sldArnPaddle.Value - pad.X}))
);
// 1. Auto pilot: reactive avoidance. Push the heading away from the closest point of the nearest
//    thing, scaled by threat (0 far .. 1 touching). No planning, no memory, one rule per tick.
If(gAuto && !IsBlank(Nearest) && Nearest.Gap < gSensor,
    With(
        {nx: gPos.x - NearestPt.x, ny: gPos.y - NearestPt.y},
        With(
            {len: Sqrt(nx ^ 2 + ny ^ 2)},
            If(len > 0,
                With(
                    {sx: gDir.x + 0.35 * Threat * nx / len, sy: gDir.y + 0.35 * Threat * ny / len},
                    With(
                        {sl: Sqrt(sx ^ 2 + sy ^ 2)},
                        If(sl > 0, Set(gDir, {x: sx / sl, y: sy / sl}))
                    )
                )
            )
        )
    )
);
// 2. Sweep: earliest contact inside this tick (0 <= T < 1) across everything, walls included.
With(
    {hit: First(Sort(Filter(Sensor, T >= 0 && T < 1), T))},
    If(IsBlank(hit),
        // free flight
        Set(gPos, {x: gPos.x + Vel.x, y: gPos.y + Vel.y}),
        // contact: advance to the contact point (a hair short so we stay outside), then respond
        With(
            {
                t: hit.T * 0.999,
                ax: ImpactAxis(gPos.x, gPos.y, gRadius, hit.RVX, hit.RVY, hit.X, hit.Y, hit.W, hit.H)
            },
            Set(gPos, {x: gPos.x + Vel.x * t, y: gPos.y + Vel.y * t});
            // reflect the heading on the face normal, but only if the ball itself was heading into
            // the face (if a faster obstacle ran into us from behind, keep going, it will pass)
            Set(gDir,
                {
                    x: If(ax = 1 && Sgn(gDir.x) = Sgn(hit.RVX), -gDir.x, gDir.x),
                    y: If(ax = 2 && Sgn(gDir.y) = Sgn(hit.RVY), -gDir.y, gDir.y)
                }
            );
            Set(gLastHit, hit.Name);
            Set(gLastHitTick, gTick);
            Switch(hit.Kind,
                "block", Set(gHits, gHits + 1),
                "paddle", Set(gSaves, gSaves + 1),
                If(hit.Id = -4, Set(gMisses, gMisses + 1))
            )
        )
    )
);
// 3. The world moves too: blocks drift and bounce inside their lane, the paddle follows the slider.
UpdateIf(colObstacles, Kind = "block",
    {
        X: X + VX * gDrift,
        Y: Y + VY * gDrift,
        VX: If((X + VX * gDrift < 0 && VX < 0) || (X + VX * gDrift + W > FieldW && VX > 0), -VX, VX),
        VY: If((Y + VY * gDrift < 0 && VY < 0) || (Y + VY * gDrift + H > FieldH - LaneH && VY > 0), -VY, VY)
    }
);
UpdateIf(colObstacles, Kind = "paddle", {X: X + VX});
Set(gTick, gTick + 1)
